  "focus.listitem": {"ko":"{n}번, {name}.","en":"Number {n}, {name}.","ja":"{n}番、{name}。","zh":"第{n}个，{name}。","vi":"Số {n}, {name}.","th":"ลำดับที่ {n} {name}","ru":"Номер {n}, {name}.","id":"Nomor {n}, {name}."},
  "focus.tab": {"ko":"{label} 탭, {total}개 중 {i}번째.","en":"{label} tab, {i} of {total}.","ja":"{label}タブ、{total}個中{i}番目。","zh":"{label}标签，共{total}个中的第{i}个。","vi":"Thẻ {label}, {i} trên {total}.","th":"แท็บ {label} ที่ {i} จาก {total}","ru":"Вкладка {label}, {i} из {total}.","id":"Tab {label}, {i} dari {total}."},
  "focus.disabled": {"ko":"{label}, 지금은 쓸 수 없습니다.","en":"{label}, not available now.","ja":"{label}、現在は使用できません。","zh":"{label}，暂时无法使用。","vi":"{label}, hiện không dùng được.","th":"{label} ใช้งานไม่ได้ในขณะนี้","ru":"{label}, сейчас недоступно.","id":"{label}, belum bisa digunakan."},
  "state.loading": {"ko":"불러오는 중입니다.","en":"Loading.","ja":"読み込み中です。","zh":"正在加载。","vi":"Đang tải.","th":"กำลังโหลด","ru":"Загрузка.","id":"Memuat."},
  "state.error.network": {"ko":"연결에 문제가 있습니다. 잠시 후 다시 시도해 주세요.","en":"There's a connection problem. Please try again shortly.","ja":"接続に問題があります。しばらくしてからもう一度お試しください。","zh":"连接出现问题，请稍后再试。","vi":"Có lỗi kết nối. Vui lòng thử lại sau.","th":"การเชื่อมต่อมีปัญหา กรุณาลองใหม่อีกครั้ง","ru":"Проблема со связью. Попробуйте чуть позже.","id":"Ada masalah koneksi. Silakan coba lagi nanti."},
  "state.empty": {"ko":"찾는 결과가 없습니다.","en":"No results found.","ja":"該当する結果がありません。","zh":"没有找到结果。","vi":"Không có kết quả.","th":"ไม่พบผลลัพธ์","ru":"Ничего не найдено.","id":"Tidak ada hasil."},
  "state.preparing": {"ko":"준비 중인 기능입니다.","en":"This feature is coming soon.","ja":"準備中の機能です。","zh":"该功能正在准备中。","vi":"Tính năng đang được chuẩn bị.","th":"ฟีเจอร์นี้กำลังจัดเตรียม","ru":"Эта функция скоро появится.","id":"Fitur ini segera hadir."},
